CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),first_name varchar(100) NOT NULL,last_name varchar(100) NOT NULL,phone varchar(20) NOT NULL,email varchar(254),birth_date date,notes text,status varchar(20) NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,created_by uuid REFERENCES administrators(id) ON DELETE SET NULL,updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL);CREATE INDEX customers_name_idx ON customers(last_name,first_name);CREATE INDEX customers_phone_idx ON customers(phone);CREATE INDEX customers_status_idx ON customers(status);
CREATE TABLE customer_public_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,public_token_hash varchar(64) NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,expires_at timestamptz,active boolean NOT NULL DEFAULT true);CREATE INDEX customer_tokens_customer_idx ON customer_public_tokens(customer_id);CREATE INDEX customer_tokens_active_idx ON customer_public_tokens(active);
CREATE TABLE loyalty_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enabled boolean NOT NULL DEFAULT false,currency varchar(3) NOT NULL DEFAULT 'MXN',purchase_rules jsonb NOT NULL DEFAULT '[]',reward_units integer NOT NULL,reward_discount_percent numeric(5,2) NOT NULL,reward_name varchar(150) NOT NULL,reward_description text NOT NULL,allow_manual_adjustments boolean NOT NULL DEFAULT false,allow_negative_balance boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL,CONSTRAINT loyalty_reward_units_positive CHECK(reward_units>0),CONSTRAINT loyalty_discount_range CHECK(reward_discount_percent>=0 AND reward_discount_percent<=100));CREATE UNIQUE INDEX loyalty_settings_singleton_idx ON loyalty_settings((true));
CREATE TABLE customer_loyalty_balance(customer_id uuid PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE,available_units integer NOT NULL DEFAULT 0,pending_units integer NOT NULL DEFAULT 0,lifetime_units integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT loyalty_pending_nonnegative CHECK(pending_units>=0),CONSTRAINT loyalty_lifetime_nonnegative CHECK(lifetime_units>=0));
CREATE TABLE customer_rewards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,reward_name varchar(150) NOT NULL,reward_discount_percent numeric(5,2) NOT NULL,required_units integer NOT NULL,status varchar(20) NOT NULL DEFAULT 'available',created_at timestamptz NOT NULL DEFAULT now(),redeemed_at timestamptz,expires_at timestamptz);CREATE INDEX customer_rewards_customer_idx ON customer_rewards(customer_id);CREATE INDEX customer_rewards_status_idx ON customer_rewards(status);
